from pathlib import Path
import re
root=Path(__file__).resolve().parent
source=(root/'index.html').read_text(encoding='utf-8')
head=source[:source.index('<body>')].replace('Software Development, Web Design & Digital Marketing | Netofficials','Custom Software & Web Application Development | Netofficials')
head=head.replace('</head>','<link rel="stylesheet" href="software-led.css"></head>')
head=re.sub(r'<meta name="description"[^>]*>','<meta name="description" content="Custom software, web applications and business websites from an India-based team. Discuss your development project with Netofficials.">',head)
def section(identifier):
 start=source.index('<section class="section',source.index('id="'+identifier+'"')-50)
 return source[start:source.index('</section>',start)+10]
approach=section('approach').replace('new application, a better website or a clearer search strategy','new application or a better website').replace('Build or improve','Develop & review').replace('development or marketing priorities','development priorities').replace('Measure next steps','Launch & evolve').replace('Review the work against your goals and decide what comes next.','Agree acceptance criteria, prepare for handover and discuss ongoing support.')
