cardhtml=''.join(f'<article class="catalog-card"><div class="catalog-top"><span class="catalog-icon" aria-hidden="true">{n}</span><small>DEVELOPMENT</small></div><h3>{title}</h3><p>{description}</p><div class="catalog-links"><a href="#contact" data-service="{service}">{cta}<span aria-hidden="true">↗</span></a></div></article>' for n,title,description,service,cta in cards)
